package com.payments.gateway;

import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;

public class PaymentCallbackProcessor {

    private static final Set<String> ALLOWED_SCHEMES = Set.of("https");
    private static final int CALLBACK_TIMEOUT_MS = 5000;
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final ConcurrentHashMap<String, MerchantConfig> merchantRegistry = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, CallbackResolution> resolutionCache = new ConcurrentHashMap<>();

    public static class MerchantConfig {
        public final String merchantId;
        public final String callbackDomain;
        public final byte[] hmacKey;

        public MerchantConfig(String merchantId, String callbackDomain, byte[] hmacKey) {
            this.merchantId = merchantId;
            this.callbackDomain = callbackDomain;
            this.hmacKey = hmacKey;
        }
    }

    public static class CallbackResolution {
        public final String resolvedHost;
        public final InetAddress resolvedAddress;
        public final long resolvedAt;

        public CallbackResolution(String resolvedHost, InetAddress resolvedAddress, long resolvedAt) {
            this.resolvedHost = resolvedHost;
            this.resolvedAddress = resolvedAddress;
            this.resolvedAt = resolvedAt;
        }
    }

    public static class PaymentNotification {
        public final String merchantId;
        public final String transactionId;
        public final String amount;
        public final String callbackPath;
        public final String signature;

        public PaymentNotification(String merchantId, String transactionId, String amount, String callbackPath, String signature) {
            this.merchantId = merchantId;
            this.transactionId = transactionId;
            this.amount = amount;
            this.callbackPath = callbackPath;
            this.signature = signature;
        }
    }

    public void registerMerchant(MerchantConfig config) {
        merchantRegistry.put(config.merchantId, config);
    }

    public CompletableFuture<Boolean> processPaymentCallback(PaymentNotification notification) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                MerchantConfig config = merchantRegistry.get(notification.merchantId);
                if (config == null) {
                    throw new SecurityException("Unknown merchant: " + notification.merchantId);
                }

                if (!verifySignature(notification, config.hmacKey)) {
                    throw new SecurityException("Invalid signature for transaction: " + notification.transactionId);
                }

                URI callbackUri = buildCallbackUri(config, notification);
                return executeCallback(callbackUri, notification);
            } catch (Exception e) {
                throw new CompletionException(e);
            }
        }, executor);
    }

    private boolean verifySignature(PaymentNotification notification, byte[] key) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKey = new SecretKeySpec(key, "HmacSHA256");
            mac.init(secretKey);
            String payload = notification.merchantId + "|" + notification.transactionId + "|" + notification.amount;
            byte[] computed = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            return MessageDigest.isEqual(Base64.getEncoder().encode(computed), notification.signature.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            return false;
        }
    }

    private URI buildCallbackUri(MerchantConfig config, PaymentNotification notification) throws URISyntaxException {
        String normalizedPath = normalizePath(notification.callbackPath);
        URI constructed = new URI("https", config.callbackDomain, normalizedPath, null);
        return constructed;
    }

    private String normalizePath(String path) {
        if (path == null || path.isEmpty()) {
            return "/callback";
        }
        // Decode percent-encoded sequences for normalization
        String decoded = urlDecode(path);
        // Remove directory traversal attempts
        decoded = decoded.replace("..", "");
        // Ensure path starts with /
        if (!decoded.startsWith("/")) {
            decoded = "/" + decoded;
        }
        return decoded;
    }

    private String urlDecode(String input) {
        try {
            return URLDecoder.decode(input, StandardCharsets.UTF_8.name());
        } catch (Exception e) {
            return input;
        }
    }

    private boolean executeCallback(URI callbackUri, PaymentNotification notification) throws Exception {
        // Pre-resolve and validate the target address
        CallbackResolution resolution = resolveAndValidate(callbackUri);

        // Build the actual connection URL using resolved address
        URL targetUrl = callbackUri.toURL();
        HttpURLConnection conn = (HttpURLConnection) targetUrl.openConnection();
        conn.setRequestMethod("POST");
        conn.setConnectTimeout(CALLBACK_TIMEOUT_MS);
        conn.setReadTimeout(CALLBACK_TIMEOUT_MS);
        conn.setDoOutput(true);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setRequestProperty("X-Transaction-Id", notification.transactionId);

        String body = String.format("{\"txn\":\"%s\",\"amount\":\"%s\",\"status\":\"completed\"}",
                notification.transactionId, notification.amount);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int responseCode = conn.getResponseCode();
        conn.disconnect();
        return responseCode >= 200 && responseCode < 300;
    }

    private CallbackResolution resolveAndValidate(URI uri) throws Exception {
        String host = uri.getHost();
        String cacheKey = host + ":" + uri.getPort();

        // Check cache first
        CallbackResolution cached = resolutionCache.get(cacheKey);
        if (cached != null && (System.currentTimeMillis() - cached.resolvedAt) < 30000) {
            validateAddress(cached.resolvedAddress);
            return cached;
        }

        // Resolve DNS
        InetAddress resolved = InetAddress.getByName(host);
        validateAddress(resolved);

        CallbackResolution resolution = new CallbackResolution(host, resolved, System.currentTimeMillis());
        resolutionCache.put(cacheKey, resolution);
        return resolution;
    }

    private void validateAddress(InetAddress address) throws SecurityException {
        if (address.isLoopbackAddress() || address.isLinkLocalAddress() ||
            address.isSiteLocalAddress() || address.isAnyLocalAddress()) {
            throw new SecurityException("Callback target resolves to internal address: " + address.getHostAddress());
        }
    }

    public CompletableFuture<Boolean> processWithRetry(PaymentNotification notification, int maxRetries) {
        return processPaymentCallback(notification).thenApply(result -> {
            if (!result && maxRetries > 0) {
                // Invalidate cache on failure to force re-resolution
                MerchantConfig config = merchantRegistry.get(notification.merchantId);
                if (config != null) {
                    resolutionCache.remove(config.callbackDomain + ":-1");
                }
                return processWithRetry(notification, maxRetries - 1).join();
            }
            return result;
        });
    }
}
